function renderHeat(){
 const $=id=>document.getElementById(id), cfg=JSON.parse($('map-initial').textContent),{rows,meta,year}=cfg;
 const fmtN=v=>new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(v),usd=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
 const short=v=>(Math.abs(v)>=1e9?'$'+fmtN(v/1e9)+'B':Math.abs(v)>=1e6?'$'+fmtN(v/1e6)+'M':Math.abs(v)>=1e3?'$'+fmtN(v/1e3)+'K':usd(v));
 const parameter=new URLSearchParams(location.search), initial=parameter.get('state');
 let state=Object.hasOwn(rows,initial)?initial:'VT';
 const map=$('usa'), colors=['#284c3e','#3c7558','#609b70','#89bd82','#bce5a6'];
 function show(){
  const metric=meta.find(x=>x[0]===$('metric').value)||meta[0], idx=metric[2], kind=metric[3];
  $('normalize').disabled=kind==='pct';
  const relative=kind!=='pct'&&$('normalize').value==='resident';
  const value=r=>kind==='pct'?(r[idx]/r[idx+1]-1)*100:relative?r[idx]/r[7]*(kind==='usd'?1:1000):r[idx];
  const display=(v,compact=false)=>kind==='pct'?(v>=0?'+':'')+fmtN(v)+'%':kind==='usd'?(relative?usd(v)+' / resident':compact?short(v):usd(v)):(relative?fmtN(v)+' / 1,000':fmtN(v));
  const levels=Object.values(rows).map(value).sort((a,b)=>a-b);
  // Relative placement by rank keeps smaller states distinguishable; legend shows actual cutoffs.
  const thresholds=[1,2,3,4].map(p=>levels[Math.ceil(p*levels.length/5)-1]);
  const band=v=>thresholds.reduce((n,t)=>n+(v>t?1:0),0);
  $('caption').textContent=metric[4]+(relative?' Normalized against the Census July '+year+' resident estimates.':'');
  $('legend').replaceChildren(...colors.map((color,i)=>{
   const l=document.createElement('li'),k=document.createElement('span');k.style.background=color;l.append(k, (i===0?'≤ '+display(thresholds[0],true):i===4?'> '+display(thresholds[3],true):display(thresholds[i-1],true)+' – '+display(thresholds[i],true)));return l;
  }));
  for(const node of map.querySelectorAll('[data-state]')){
   const ab=node.dataset.state,r=rows[ab],v=value(r),label=r[0]+': '+display(v);
   node.classList.toggle('selected',state===ab);node.setAttribute('aria-pressed',String(state===ab));node.setAttribute('aria-label',label);
   node.querySelector('title').textContent=label;node.style.fill=colors[band(v)];
  }
  const rank=Object.keys(rows).sort((a,b)=>value(rows[b])-value(rows[a]));
  const r=rows[state];
  $('state-pick').value=state;$('selected-name').textContent=r[0];$('selected-measure').textContent=display(value(r),true);$('selected-measure').title=display(value(r));$('selected-measure').setAttribute('aria-label',display(value(r)));$('selected-metric').textContent=year+' · '+metric[1];
  $('selected-rank').textContent=(rank.indexOf(state)+1)+' of '+rank.length;
  $('selected-pop').textContent=fmtN(r[7]);$('selected-units').textContent=fmtN(r[2]);$('selected-spend').textContent=short(r[3]);$('selected-public').textContent=short(r[5]);
  $('market-link').href='/admin/spend-clock/?state='+encodeURIComponent(state);
  $('source-link').href=cfg.sources[metric[5]][1];
  const old=$('ranks').scrollTop;
  $('ranks').replaceChildren(...rank.map(ab=>{
   const l=document.createElement('li'),b=document.createElement('button'),n=document.createElement('span'),v=document.createElement('span');
   b.type='button';b.setAttribute('aria-current',String(ab===state));n.textContent=rows[ab][0];v.textContent=display(value(rows[ab]),true);b.append(n,v);l.append(b);
   b.onclick=()=>{select(ab);$('selected-name').focus({preventScroll:true});};return l;
  }));
  $('ranks').scrollTop=old;
 }
 function select(ab){if(!Object.hasOwn(rows,ab))return;state=ab;const u=new URL(location.href);u.searchParams.set('state',ab);history.replaceState(null,'',u);show();}
 map.onclick=e=>select(e.target.closest('[data-state]')?.dataset.state);
 map.onkeydown=e=>{if(e.key!=='Enter'&&e.key!==' ')return;const ab=e.target.closest('[data-state]')?.dataset.state;if(!ab)return;e.preventDefault();select(ab);};
 $('map-zoom').onclick=()=>{
  const flag=$('map-zoom').getAttribute('aria-pressed')==='true';
  if(!flag){
   const boxes=['ME','NH','VT','NY','CT','MA','RI','NJ','PA','MD','DE','DC'].map(a=>map.querySelector('g[data-state="'+a+'"]').getBBox());
   const x=Math.min(...boxes.map(p=>p.x))-9,y=Math.min(...boxes.map(p=>p.y))-9, xmax=Math.max(898,...boxes.map(p=>p.x+p.width))+9,ymax=Math.max(...boxes.map(p=>p.y+p.height))+9;
   map.setAttribute('viewBox',[x,y,xmax-x,ymax-y].join(' '));
  }else map.setAttribute('viewBox',cfg.frame);
  $('map-zoom').setAttribute('aria-pressed',String(!flag));$('map-zoom').textContent=flag?'Zoom Northeast':'Reset map view';
 };
 $('metric').onchange=show;$('normalize').onchange=show;$('state-pick').onchange=e=>select(e.target.value);
 show();
}
export function heatmapHtml(){
 const entries=Object.entries(heatRows);
 const states=entries.map(([ab,r])=>'<g class="state" tabindex="0" role="button" data-state="'+ab+'"><title>'+r[0]+'</title><path class="boundary" d="'+r[8]+'"></path>'+(heatMarkers[ab]?'<circle class="dc-mark" cx="'+heatMarkers[ab][0]+'" cy="'+heatMarkers[ab][1]+'" r="3"/>':'')+'</g>').join('');
 const labels=entries.map(([ab])=>{
  const [x,y]=heatLabelAnchors[ab], callout=heatLabelCallouts[ab];
  return callout?'<path class="state-line" d="M'+x+','+y+' L854,'+(callout[1]-3)+' H871"/><text class="state-label callout" x="'+callout[0]+'" y="'+callout[1]+'">'+ab+'</text>':'<text class="state-label" x="'+x+'" y="'+(y+3.5)+'">'+ab+'</text>';
 }).join('');
 const data=Object.fromEntries(entries.map(([ab,r])=>[ab,r.slice(0,8)]));
 const options=[...entries].sort((a,b)=>a[1][0].localeCompare(b[1][0])).map(([ab,r])=>'<option value="'+ab+'">'+r[0]+'</option>').join('');
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>U.S. Construction Heat Map | Vermont Spend Clock</title><style>'+heatCSS+'</style></head><body><main><header class="mast"><div><div class="eyebrow">VERMONT SPEND CLOCK / NATIONAL VIEW</div><h1>U.S. construction heat map</h1><p>Compare all 50 states and D.C. by building activity and construction spending.</p></div><a class="button" href="/admin/spend-clock/">Back to the Spend Clock</a></header>'+
 '<div class="controls"><label>Color the map by<select id="metric">'+heatMeta.map(m=>'<option value="'+m[0]+'"'+(m[0]==='private'?' selected':'')+'>'+m[1]+'</option>').join('')+'</select></label><label>Scale<select id="normalize"><option value="total">Total</option><option value="resident">Per resident</option></select></label><button class="button" id="map-zoom" type="button" aria-pressed="false">Zoom Northeast</button><label>Inspect a state<select id="state-pick">'+options+'</select></label></div><p id="caption"></p>'+
 '<div class="workspace"><div class="panel map-panel"><svg id="usa" viewBox="'+heatFrame+'" aria-label="Construction activity by U.S. state"><rect class="inset-frame" x="20" y="396" width="173" height="153" rx="4"/><rect class="inset-frame" x="197" y="477" width="109" height="72" rx="4"/>'+states+'<g aria-hidden="true">'+labels+'</g></svg><ul id="legend" aria-label="Map color scale"></ul></div><aside class="side"><section class="panel record" aria-label="Selected state" aria-live="polite"><h2 id="selected-name" tabindex="-1"></h2><div class="measure" id="selected-measure"></div><p id="selected-metric"></p><dl><dt>Rank for selected measure</dt><dd id="selected-rank"></dd><dt>Residents</dt><dd id="selected-pop"></dd><dt>New housing units</dt><dd id="selected-units"></dd><dt>Private nonresidential</dt><dd id="selected-spend"></dd><dt>State and local construction</dt><dd id="selected-public"></dd></dl><a id="market-link" class="button" href="/admin/spend-clock/">Open market dashboard</a></section><section class="panel ranking"><h2>State rankings</h2><ol id="ranks"></ol></section></aside></div>'+
 '<footer><div>Published '+heatYear+' annual Census data, not a live counter. Rankings compare the selected measure; lighter greens indicate higher readings. Alaska and Hawaii are rescaled insets. <a id="source-link" href="'+heatSources[1][1]+'">Source for selected measure</a></div>'+heatSources.map(([label,url])=>'<a href="'+url+'">'+label+'</a>').join('')+'</footer></main><script id="map-initial" type="application/json">'+JSON.stringify({rows:data,meta:heatMeta,year:heatYear,frame:heatFrame,sources:heatSources})+'</script><script>('+renderHeat.toString()+')();</script></body></html>';
}
